import { Injectable } from '@nestjs/common';
import { and, desc, eq, inArray } from 'drizzle-orm';
import { audit, enqueue, precondition, QUEUES, type Actor } from '@projecthub/core';
import { artifacts, jobs, previews } from '@projecthub/database';
import { Ctx, type AuthInfo } from '../../infra/context.js';
import { ProjectAccess } from '../../infra/project-access.js';

/** User guide and presentation PDFs, generated by the worker from a running preview. */
@Injectable()
export class GuideService {
  constructor(
    private readonly ctx: Ctx,
    private readonly access: ProjectAccess,
  ) {}

  async overview(auth: AuthInfo, idOrSlug: string) {
    const scope = await this.access.require(auth, idOrSlug);
    const ready = await this.ctx.db
      .select({ id: previews.id, slug: previews.slug, branch: previews.sourceBranch, commit: previews.sourceCommit, createdAt: previews.createdAt })
      .from(previews)
      .where(and(eq(previews.projectId, scope.project.id), eq(previews.status, 'ready')))
      .orderBy(desc(previews.createdAt));
    const docs = await this.ctx.db
      .select({ id: artifacts.id, fileName: artifacts.fileName, sizeBytes: artifacts.sizeBytes, createdAt: artifacts.createdAt })
      .from(artifacts)
      .where(and(eq(artifacts.projectId, scope.project.id), eq(artifacts.type, 'report'), eq(artifacts.contentType, 'application/pdf')))
      .orderBy(desc(artifacts.createdAt))
      .limit(20);
    const job = (
      await this.ctx.db
        .select({ id: jobs.id, status: jobs.status, error: jobs.lastError, createdAt: jobs.createdAt, finishedAt: jobs.finishedAt, result: jobs.result })
        .from(jobs)
        .where(and(eq(jobs.projectId, scope.project.id), eq(jobs.type, 'guide.generate')))
        .orderBy(desc(jobs.createdAt))
        .limit(1)
    )[0];
    return {
      previews: ready,
      job: job ?? null,
      documents: docs.map((d) => ({ ...d, kind: d.fileName.endsWith('-sunum.pdf') ? 'slides' : 'guide' })),
      canGenerate: scope.can('review.create') && scope.project.status !== 'archived',
    };
  }

  async generate(auth: AuthInfo, idOrSlug: string, previewId: string, actor: Actor) {
    const scope = await this.access.requireWritable(auth, idOrSlug, 'review.create');
    const pv = (await this.ctx.db.select().from(previews).where(and(eq(previews.id, previewId), eq(previews.projectId, scope.project.id))))[0];
    if (!pv || pv.status !== 'ready') throw precondition('Kılavuz yalnızca çalışan (hazır) bir ön izlemeden hazırlanabilir');
    const busy = await this.ctx.db.select({ id: jobs.id }).from(jobs).where(and(eq(jobs.projectId, scope.project.id), eq(jobs.type, 'guide.generate'), inArray(jobs.status, ['queued', 'running'])));
    if (busy.length) throw precondition('Bu proje için kılavuz zaten hazırlanıyor');
    await enqueue(this.ctx.db, { queue: QUEUES.browser, type: 'guide.generate', organizationId: auth.organizationId, projectId: scope.project.id, maxAttempts: 1, payload: { projectId: scope.project.id, previewId: pv.id, requestedBy: auth.user.id } });
    await audit(this.ctx.db, { organizationId: auth.organizationId, projectId: scope.project.id, actor, action: 'guide.requested', resourceType: 'preview', resourceId: pv.id });
    return { queued: true };
  }
}
